import sys
from functools import lru_cache

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    t = int(data[0])
    nums = list(map(int, data[1:]))

    @lru_cache(maxsize=None)
    def can_first_win(residue: int, moves_left: int, turn: int) -> bool:
        """
        Returns True if Vanya (the first player) can force a win from the given state.
        residue : current value modulo 3 (0,1,2)
        moves_left : number of moves still allowed (including the current one)
        turn : 0 -> Vanya's turn, 1 -> Vova's turn
        """
        if moves_left == 0:
            # No moves left, Vova wins
            return False

        # possible next residues after adding or subtracting 1
        next_residues = [(residue + 1) % 3, (residue - 1) % 3]

        if turn == 0:  # Vanya's move
            # He wins instantly if any move makes the number divisible by 3
            for nr in next_residues:
                if nr == 0:
                    return True
            # Otherwise, he chooses a move that leads to a winning state later
            for nr in next_residues:
                if can_first_win(nr, moves_left - 1, 1):
                    return True
            return False
        else:  # Vova's move
            # Vova tries to force a state where Vanya cannot win.
            # Vanya wins only if *both* possible moves still let him win.
            for nr in next_residues:
                if not can_first_win(nr, moves_left - 1, 0):
                    return False
            return True

    out_lines = []
    for n in nums:
        start_residue = n % 3
        if can_first_win(start_residue, 10, 0):
            out_lines.append("First")
        else:
            out_lines.append("Second")
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

