    t = int(next(it))
    out_lines = []
    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # prefix sums
        pref = [0] * (n + 1)
        for i in range(n):
            pref[i + 1] = pref[i] + a[i]

        # collect all divisors of n
        divs = []
        i = 1
        while i * i <= n:
            if n % i == 0:
                divs.append(i)
                if i * i != n:
                    divs.append(n // i)
            i += 1

        best = 0  # at least 0 (k = n)
        for k in divs:
            # compute min and max block sum of length k
            mn = 10**30
            mx = -10**30
            for start in range(0, n, k):
                cur = pref[start + k] - pref[start]
                if cur < mn:
                    mn = cur
                if cur > mx:
                    mx = cur
            diff = mx - mn
            if diff > best:
                best = diff

        out_lines.append(str(best))

    sys.stdout.write("\n".join(out_lines))

