import math

def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    t = int(next(it))
    out_lines = []
    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # prefix sums
        pref = [0] * (n + 1)
        for i in range(1, n + 1):
            pref[i] = pref[i - 1] + a[i - 1]

        # all divisors of n
        divs = []
        for d in range(1, int(math.isqrt(n)) + 1):
            if n % d == 0:
                divs.append(d)
                if d * d != n:
                    divs.append(n // d)

        best = 0  # at least 0 (k = n gives one truck)
        for k in divs:
            # compute max and min block sum of size k
            max_sum = -10**30
            min_sum = 10**30
            for i in range(k, n + 1, k):
                cur = pref[i] - pref[i - k]
                if cur > max_sum:
                    max_sum = cur
                if cur < min_sum:
                    min_sum = cur
            diff = max_sum - min_sum
            if diff > best:
                best = diff

        out_lines.append(str(best))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
